{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None), event("b", 1, False)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False)] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["  # comment, not a record", "", "  \t", " a , 1 , 1 ", "b, -2, 0", "c,3,  "]
    assert parse_transcript_log(lines) == [event("a", 1, True), event("b", -2, False), event("c", 3, None)]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,true"])
def test_parse_invalid_line_reports_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", " ", "x,1,1", line])


def test_dedupe_keeps_last_duplicate_then_sorts_by_day_and_id():
    events = [event("a", 0, True), event("z", 2, True), event("b", 2, True),
              event("a", 2, False), event("z", 1, None)]
    assert dedupe_transcripts(events) == [events[4], events[3], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_gaps():
    events = [event("a", 1, True), event("b", 1, True), event("c", 2, None),
              event("d", 3, False), event("e", 4, True), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 2, 2) == [0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_summary_pooled_rate_calendar_window_and_nonempty_groups():
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 4, True), event("c", 4, False), event("d", 5, None),
              event("e", 5, False), event("f", 5, False)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 2
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({"a": [event("a", 1, True), event("b", 5, False)]}, 2)["recent"] == 0


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "b": [event("b", 1, False)],
              "a": [event("a", 1, True)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 2) == []


def test_flag_rate_by_group_sorted_including_empty():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


def test_longest_streak_requires_consecutive_positive_counts():
    assert longest_flag_streak([1, 2, 0, 3, 4, 5, -1, 1]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
